import{c as t,Q as e,j as s,m as n}from"./chunks/framework.BPKcPtvA.js";const b=JSON.parse('{"title":"vLLM 高性能推理优化","description":"","frontmatter":{},"headers":[],"relativePath":"05-engineering-tools/vllm-inference.md","filePath":"05-engineering-tools/vllm-inference.md"}'),i={name:"05-engineering-tools/vllm-inference.md"};function l(r,a,d,o,h,p){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="vllm-高性能推理优化" tabindex="-1">vLLM 高性能推理优化 <a class="header-anchor" href="#vllm-高性能推理优化" aria-label="Permalink to &quot;vLLM 高性能推理优化&quot;">​</a></h1><blockquote><p>PagedAttention 与多模态量化调优 —— 让模型推理飞起来</p></blockquote><h2 id="为什么需要-vllm" tabindex="-1">为什么需要 vLLM？ <a class="header-anchor" href="#为什么需要-vllm" aria-label="Permalink to &quot;为什么需要 vLLM？&quot;">​</a></h2><p>LLM 推理的瓶颈不在于计算能力，而在于<strong>显存管理</strong>。标准 Transformer 推理的 KV Cache 管理存在严重的显存碎片化问题，导致实际吞吐量远低于理论峰值。</p><h3 id="传统问题" tabindex="-1">传统问题 <a class="header-anchor" href="#传统问题" aria-label="Permalink to &quot;传统问题&quot;">​</a></h3><ul><li><strong>KV Cache 膨胀</strong>：每个 Token 的 Key/Value 向量需要缓存，长序列下显存爆炸</li><li><strong>显存碎片</strong>：预分配固定大小导致大量空闲显存无法利用</li><li><strong>请求并发低</strong>：碎片化显存限制了 Batch Size</li></ul><h2 id="pagedattention-核心原理" tabindex="-1">PagedAttention 核心原理 <a class="header-anchor" href="#pagedattention-核心原理" aria-label="Permalink to &quot;PagedAttention 核心原理&quot;">​</a></h2><p>vLLM 的核心创新是 <strong>PagedAttention</strong> —— 借鉴操作系统虚拟内存的分页思想管理 KV Cache。</p><h3 id="类比操作系统" tabindex="-1">类比操作系统 <a class="header-anchor" href="#类比操作系统" aria-label="Permalink to &quot;类比操作系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作系统</th><th>vLLM</th></tr></thead><tbody><tr><td>物理内存 → 页框 (Page Frame)</td><td>GPU 显存 → KV Block</td></tr><tr><td>虚拟内存 → 页表</td><td>逻辑 KV Cache → Block Table</td></tr><tr><td>进程分配连续虚拟地址</td><td>请求分配连续逻辑 KV Cache</td></tr><tr><td>实际物理内存可以不连续</td><td>实际 KV Block 可以不连续</td></tr><tr><td>避免外部碎片</td><td>避免 KV Cache 碎片</td></tr></tbody></table><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 请求到达，分配逻辑 KV Cache</span></span>
<span class="line"><span>2. Block Table 将逻辑位置映射到物理 KV Block</span></span>
<span class="line"><span>3. Prefill 阶段：一次处理整个 Prompt，生成 KV Cache</span></span>
<span class="line"><span>4. Decode 阶段：逐 Token 生成，追加到对应 Block</span></span>
<span class="line"><span>5. Block 写满则分配新 Block</span></span>
<span class="line"><span>6. 请求完成后释放所有 Block</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">性能收益</p><p>PagedAttention 将 KV Cache 浪费从模型内存的 60-80% 降至 4% 以下，吞吐量提升约 <strong>24×</strong>（相比于 HuggingFace Transformers）。</p></div><h2 id="连续批处理" tabindex="-1">连续批处理 <a class="header-anchor" href="#连续批处理" aria-label="Permalink to &quot;连续批处理&quot;">​</a></h2><p>vLLM 的 Continuous Batching 允许请求动态加入和离开批处理：</p><ul><li>传统静态批处理：所有请求需同时完成才能处理下一批</li><li>连续批处理：完成的请求立即移出，新请求立即加入</li><li>迭代级调度：每个 Decode Step 都可以调整批处理组合</li></ul><h2 id="多模态量化调优" tabindex="-1">多模态量化调优 <a class="header-anchor" href="#多模态量化调优" aria-label="Permalink to &quot;多模态量化调优&quot;">​</a></h2><h3 id="量化基础" tabindex="-1">量化基础 <a class="header-anchor" href="#量化基础" aria-label="Permalink to &quot;量化基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>精度</th><th>每参数比特</th><th>适用场景</th></tr></thead><tbody><tr><td>FP32</td><td>32</td><td>训练（全精度）</td></tr><tr><td>FP16</td><td>16</td><td>推理基准</td></tr><tr><td>BF16</td><td>16</td><td>训练（更好的动态范围）</td></tr><tr><td>INT8</td><td>8</td><td>推理加速</td></tr><tr><td>INT4 / NF4</td><td>4</td><td>边缘部署</td></tr></tbody></table><h3 id="awq-量化" tabindex="-1">AWQ 量化 <a class="header-anchor" href="#awq-量化" aria-label="Permalink to &quot;AWQ 量化&quot;">​</a></h3><p>vLLM 主流使用 AWQ（Activation-aware Weight Quantization）：</p><ul><li><strong>核心洞察</strong>：并非所有权重同样重要 — 少量「显著通道」对模型质量影响更大</li><li><strong>策略</strong>：对显著通道使用 Per-Channel 缩放保护，其余通道激进量化</li></ul><h3 id="gptq-量化" tabindex="-1">GPTQ 量化 <a class="header-anchor" href="#gptq-量化" aria-label="Permalink to &quot;GPTQ 量化&quot;">​</a></h3><p>逐层最优量化，通过校准数据集求解最优量化参数。</p><h3 id="多模态模型量化特殊考量" tabindex="-1">多模态模型量化特殊考量 <a class="header-anchor" href="#多模态模型量化特殊考量" aria-label="Permalink to &quot;多模态模型量化特殊考量&quot;">​</a></h3><p>多模态 LMM 的量化比纯文本 LLM 更复杂：</p><ol><li><p><strong>视觉编码器量化</strong></p><ul><li>ViT 的激活值分布与 LLM 不同</li><li>视觉 Patch 间的注意力模式对量化更敏感</li><li>建议：视觉编码器使用 FP16/BF16，仅量化 LLM 部分</li></ul></li><li><p><strong>连接器量化</strong></p><ul><li>MLP 连接器参数量通常很小，建议保持 FP16</li><li>Cross-Attention Resampler 的注意力计算对精度敏感</li></ul></li><li><p><strong>图像 Token 数量影响</strong></p><ul><li>高分辨率输入 → 数千个视觉 Token → KV Cache 暴增</li><li>PagedAttention 在此场景收益最大</li></ul></li></ol><h2 id="vllm-部署最佳实践" tabindex="-1">vLLM 部署最佳实践 <a class="header-anchor" href="#vllm-部署最佳实践" aria-label="Permalink to &quot;vLLM 部署最佳实践&quot;">​</a></h2><h3 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to &quot;关键参数&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen2.5-VL-7B-Instruct</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dtype</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bfloat16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-model-len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8192</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --gpu-memory-utilization</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.90</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-num-seqs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-prefix-caching</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> awq</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>含义</th><th>建议值</th></tr></thead><tbody><tr><td><code>gpu-memory-utilization</code></td><td>GPU 显存使用率上限</td><td>0.85–0.95</td></tr><tr><td><code>max-num-seqs</code></td><td>最大并发序列数</td><td>根据显存和 max-model-len 计算</td></tr><tr><td><code>enable-prefix-caching</code></td><td>复用相同 Prefix 的 KV Cache</td><td>推荐开启</td></tr><tr><td><code>max-model-len</code></td><td>支持的最大序列长度</td><td>根据业务需求设置</td></tr><tr><td><code>quantization</code></td><td>量化方法</td><td>低显存场景用 awq</td></tr></tbody></table><h3 id="投机解码" tabindex="-1">投机解码 <a class="header-anchor" href="#投机解码" aria-label="Permalink to &quot;投机解码&quot;">​</a></h3><p>使用 Draft Model 快速生成候选 Token，Target Model 批量验证，在不降低质量的前提下提升 Decode 速度：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draft Model (小、快) → 生成 K 个候选 Token</span></span>
<span class="line"><span>Target Model (大、准) → 一次前向验证所有候选 → 接受/拒绝</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,34)])])}const k=t(i,[["render",l]]);export{b as __pageData,k as default};
